function Dialog({title,close,children,wide=false}:{title:string;close:()=>void;children:React.ReactNode;wide?:boolean}){
 const ref=useRef<HTMLDialogElement>(null)
 useEffect(()=>{const el=ref.current!;el.showModal();return()=>el.close()},[])
 return <dialog ref={ref} className={'ds-dialog '+(wide?'wide':'')} onCancel={event=>{event.preventDefault();close()}} onClick={event=>{if(event.target===event.currentTarget)close()}} aria-label={title}><header><h2>{title}</h2><button className="ds-icon" aria-label="Закрыть" onClick={close}><Icon name="close"/></button></header>{children}</dialog>
}
function remember<T,>(key:string,fallback:T):T{try{return JSON.parse(localStorage.getItem(key)||'null')??fallback}catch{return fallback}}
const empty:SpaceState={schemaVersion:1,revision:0,projects:[],materials:[],pages:[],tasks:[]}
