 const [collapsed,setCollapsed]=useState(saved?.collapsed??false),[agentOpen,setAgentOpen]=useState(saved?.agentOpen??false),[agentWidth,setAgentWidth]=useState(saved?.agentWidth||500)
 const [agentWide,setAgentWide]=useState(saved?.agentWide??false),[paneRequest,setPaneRequest]=useState<PaneRequest|null>(null)
 const [selected,setSelected]=useState<string[]>([])
 const [pinning,setPinning]=useState(false)
 const [topicInput,setTopicInput]=useState<string|null>(null),[renameTopic,setRenameTopic]=useState<string|null>(null)
 const [modal,setModal]=useState<Modal>(null),[commandQuery,setCommandQuery]=useState('')
