 const openMaterial=(id:string)=>{if(!id){navigation.navigate({materialId:'',filePath:''});return}const material=dataRef.current.materials.find(m=>m.id===id);if(material){navigation.navigate({projectId:material.projectId,topicId:material.topicId,view:material.archived?'archive':'materials',pageId:'',gallery:false,materialId:id,filePath:''});setDetailId(null)}}
