 const selectAgent=(session:ChatSession)=>{const assigned=desktop.settings.spaceSessionProjects?.[session.id],matching=data.projects.filter(p=>normalizePath(p.path)===normalizePath(session.cwd));const match=assigned?data.projects.find(p=>p.id===assigned):matching.length===1?matching[0]:undefined;if(match&&match.id!==project?.id)chooseProject(match.id);selectChat(session.id);setAgentOpen(true)}
