 useEffect(()=>{void refresh();return onServiceEvent(event=>{if(event.type==='devspace-changed')void refresh();if(event.type==='navigate'&&event.window==='chats')setAgentOpen(true)})},[refresh])
 const initialized=useRef(false)
 useEffect(()=>{if(!loaded||!data.projects.length||initialized.current)return;initialized.current=true;const requested=parseRoute(location.hash),owner=requested&&data.projects.find(p=>p.id===requested.projectId);if(owner&&requested&&(requested.view!=='page'||data.pages.some(p=>p.id===requested.pageId&&p.projectId===owner.id))){navigation.navigate(requested,true)}else chooseProject(data.projects.some(p=>p.id===projectId)?projectId:data.projects[0].id,true)},[loaded,data.projects.length])
 useEffect(()=>{if(!loaded||!initialized.current)return;if(!data.projects.some(p=>p.id===projectId)){chooseProject(data.projects[0].id,true);return}if(topicId!=='all'&&topicId!=='unfiled'&&!project?.topics.some(t=>t.id===topicId))navigation.navigate({topicId:'unfiled',materialId:'',filePath:''},true);if(view==='page'&&!page)navigation.navigate({view:'materials',topicId:'all',pageId:'',materialId:'',filePath:''},true)},[loaded,data.projects,projectId,topicId,view,pageId,data.pages])
 useEffect(()=>{setLegacy(false)},[navigation.route])
 const selectionCache=useRef(new Map<string,string[]>()),selectionRef=useRef(selected);selectionRef.current=selected
